  const notes = (await listNotes(db)).filter(n => !n.deleted && !BRAIN_SKIP.test(n.category || "") && plainText(n.body).length > 40);
  const due = notes.filter(n => !st.done[n.id] && !String(n.body).includes(DEEP_MARK))
