    await new Promise(r => setTimeout(r, i < 5 ? 1500 : 3000));
    const s = await fetch("https://generativelanguage.googleapis.com/v1beta/" + file.name, {headers: {"x-goog-api-key": env.GEMINI_API_KEY}});
    file = await s.json().catch(() => file);
