  imgs.length ? (noAlt ? add("pictures", noAlt > 3 ? "medium" : "low", `${noAlt} of ${imgs.length} pictures have no alt text (Google Images and screen readers use it).`) : add("pictures", "ok", `All ${imgs.length} pictures have alt text.`)) : null;
