const dealTokens = q => String(q || "").toLowerCase().replace(/(\d+)\s*(gb|tb|inch|in|"|mm)/g, "$1$2").split(/[^a-z0-9.+-]+/).filter(t => t.length > 1 && !/^(the|for|and|with|new|best|price|buy|ph|philippines|official|store)$/.test(t));
