        const p = await r.json(), vs = (p.variants || []).map(v => ({title: v.title || v.public_title || "", price: v.price / 100, was: v.compare_at_price ? v.compare_at_price / 100 : null, available: v.available}));
        const {v, sure} = pickVariant(vs, q, p.title);
