    const dept = ACT_DEPTS.includes(a.dept) ? a.dept : "general";
    await db.prepare("INSERT INTO max_activity (at, dept, kind, text, detail, model, ok, ms, source) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
