    const all = await env.MAX_MEMORY.prepare("SELECT count(*) AS c FROM max_activity WHERE at > ?").bind(t0 - 864e5).first();
    report.max.push(`Activity log: ${all?.c || 0} entries today, ${f?.c || 0} failed`);
