  const d = await getJson("https://query1.finance.yahoo.com/v8/finance/chart/" + encodeURIComponent(ticker) + "?interval=1d&period1=" + Math.floor((t - 10 * 864e5) / 1000) + "&period2=" + Math.floor((t + 864e5) / 1000));
