    if (r === "emailed" || r === "emails off" || fresh[0].at < Date.now() - 3 * 864e5) { V.emailed = Math.max(...fresh.map(e => e.id)); await srvSetting(env, "max_invest_paper", JSON.stringify(V)); }
    out.push(r);
